DO $do$
BEGIN
PERFORM setval(pg_get_serial_sequence('exam_attempts', 'id'),
(SELECT COALESCE(max(id), 0) + 1 FROM exam_attempts), false);
END
$do$;

INSERT INTO active_session (id, mode, question_numbers, answers, flagged_indexes, study_later_questions,
current_index, time_limit_seconds, auto_reveal, open_ended, live_score, draw_mode, started_at, saved_at)
SELECT id, mode, question_numbers, answers, flagged_indexes, study_later_questions,
current_index, time_limit_seconds, auto_reveal, open_ended, live_score, draw_mode, started_at, saved_at
FROM jsonb_to_recordset('[

]') AS b (
id integer, mode text, question_numbers integer[], answers jsonb, flagged_indexes integer[],
study_later_questions integer[], current_index integer, time_limit_seconds integer,
auto_reveal boolean, open_ended boolean, live_score boolean, draw_mode text,
started_at timestamptz, saved_at timestamptz)
ON CONFLICT (id) DO NOTHING;

SELECT (SELECT count(*) FROM exam_attempts) AS sessioni,
(SELECT count(*) FROM exam_attempt_answers) AS risposte,
(SELECT count(*) FROM active_session) AS sessione_in_corso;

